SELECT analytics_order_facts.month, SUM(analytics_order_facts.gross_revenue) AS gross_revenue FROM analytics_order_facts WHERE analytics_order_facts.year IN (2024, 2025) AND analytics_order_facts.region = 'East' AND analytics_order_facts.channel = 'marketplace' AND analytics_order_facts.customer_segment = 'public' GROUP BY analytics_order_facts.month ORDER BY analytics_order_facts.month ASC LIMIT 24
